import { execSync } from "node:child_process";
import { LoopRunTracker } from "./loop-run-tracker.js";
import type { RunSnapshot as LoopRunState } from "../loop-run/state.js";
import { normalizeSteeringPostCrash } from "../loop-run/state.js";
import type { GitClient } from "./git-client.js";
import { WorkspaceManager } from "./workspace.js";
import { createTtyPromptBoundary, type PromptBoundary } from "../loop-run/prompt-boundary.js";

export type RecoveryChoice = "resume" | "rollback" | "finishRollback" | "abandon" | "cancel";

export interface StaleRunRecoveryResult {
  action: "proceed" | "abort";
  message?: string;
  rollbackDisabled: boolean;
}

/**
 * Injectable interface separating the recovery decision model from terminal
 * presentation. Production callers use `ttyRecoveryPrompts`; tests can inject a
 * fake to exercise the dispatch / side-effect logic without a TTY.
 */
export interface RecoveryPrompts {
  promptChoice(state: LoopRunState, actions: RecoveryChoice[]): Promise<RecoveryChoice>;
  promptDoneInconsistency(task: LoopRunState["tasks"][string]): Promise<"restart" | "trust">;
  promptDirtyMerge(task: LoopRunState["tasks"][string]): Promise<"retry" | "abandon">;
  promptFinishRollbackConfirm(): Promise<boolean>;
}

class AbandonStaleRunError extends Error {
  constructor() {
    super("Stale run abandoned by developer during recovery.");
  }
}

/**
 * Detect a partially completed Force-Kill Undo from durable tracker state.
 * Returns true when `panicUndo` is present and the phase is anything other
 * than the terminal `rollback-completed` (which means the undo finished
 * successfully and the run should have been archived).
 */
const actionLabels: Record<RecoveryChoice, string> = {
  resume: "Resume stale run (recover unfinished work)",
  rollback: "Rollback and discard loop changes, start fresh",
  finishRollback: "Finish partial panic-undo rollback (requires confirmation)",
  abandon: "Abandon stale run, start new loop run",
  cancel: "Cancel startup, do nothing",
};

const actionShortcuts: Record<RecoveryChoice, string> = {
  resume: "R",
  rollback: "B",
  finishRollback: "F",
  abandon: "A",
  cancel: "C",
};

export function createRecoveryPromptsFromBoundary(boundary: PromptBoundary): RecoveryPrompts {
  return {
    promptChoice(state, actions) {
      return boundary.selectValue(
        `Stale loop run detected (runId: ${state.runId}, started by PID ${state.owner.pid})`,
        actions.map((action) => ({
          label: actionLabels[action],
          value: action,
          shortcut: actionShortcuts[action],
        })),
        -1, // no selected default; Enter chooses only the focused option
      );
    },

    promptDoneInconsistency(task) {
      return boundary.selectValue(
        `Task #${task.issueId} is marked done but its recorded integrated commit is not reachable from current HEAD.`,
        [
          { label: `Restart task #${task.issueId} (discard done state)`, value: "restart" },
          { label: "Trust tracker and continue (skip task)", value: "trust" },
        ],
      );
    },

    promptDirtyMerge(task) {
      return boundary.selectValue(
        "Primary repository has uncommitted changes. Merge recovery would overwrite them.",
        [
          { label: `Clean workspace manually and retry merge recovery for #${task.issueId}`, value: "retry" },
          { label: "Abandon stale run", value: "abandon" },
        ],
      );
    },

    promptFinishRollbackConfirm() {
      return boundary.selectValue(
        "Confirm Finish Rollback. This will discard all loop changes and restore the repository to its pre-loop state.",
        [
          { label: "Yes, finish rollback", value: "yes", shortcut: "Y" },
          { label: "No, cancel", value: "no", shortcut: "N" },
        ],
      ).then((value) => value === "yes");
    },
  };
}

export class StaleRun {
  public constructor(
    private state: LoopRunState,
    private readonly tracker?: LoopRunTracker,
  ) {}

  public static fromTracker(tracker: LoopRunTracker): StaleRun | null {
    if (!tracker.isStale()) {
      return null;
    }
    const state = tracker.read();
    if (!state) {
      return null;
    }
    return new StaleRun(state, tracker);
  }

  public getRunId(): string {
    return this.state.runId;
  }

  public getState(): LoopRunState {
    return this.state;
  }

  public isPartialPanicUndo(): boolean {
    const pu = this.state.panicUndo;
    if (!pu) return false;
    return pu.phase !== "rollback-completed";
  }

  public canFinishRollback(): boolean {
    if (!this.isPartialPanicUndo()) return false;
    if (this.state.panicUndo?.phase !== "processes-drained") return false;
    if (this.state.rollbackSnapshotId == null) return false;
    return true;
  }

  public getAvailableActions(): RecoveryChoice[] {
    if (this.isPartialPanicUndo()) {
      const actions: RecoveryChoice[] = ["abandon", "cancel"];
      if (this.canFinishRollback()) {
        actions.splice(0, 0, "finishRollback");
      }
      return actions;
    }

    const actions: RecoveryChoice[] = ["resume", "abandon", "cancel"];
    if (this.state.rollbackSnapshotId != null) {
      actions.splice(1, 0, "rollback");
    }
    return actions;
  }

  public normalizeCrashRules(): void {
    if (!this.tracker) return;
    const hasSubmitted = Object.values(this.state.tasks).some((task) =>
      (task.liveSteering ?? []).some((r) => r.status === "submitted"),
    );
    if (!hasSubmitted) return;

    this.tracker.normalizeLiveSteeringPostCrash();
    this.state = this.tracker.read() ?? this.state;
  }

  public async execute(
    choice: RecoveryChoice,
    deps: {
      git: GitClient;
      workspaceManager: WorkspaceManager;
      prompts: RecoveryPrompts;
    },
  ): Promise<StaleRunRecoveryResult> {
    if (!this.tracker) {
      throw new Error("Cannot execute recovery actions without a tracker.");
    }
    const { git, workspaceManager, prompts } = deps;
    switch (choice) {
      case "cancel":
        return { action: "abort", message: "Recovery cancelled by developer.", rollbackDisabled: false };

      case "abandon": {
        this.tracker.markCompletedAndArchive();
        return { action: "proceed", message: "Stale run abandoned. Starting new loop run.", rollbackDisabled: false };
      }

      case "rollback": {
        if (!this.state.rollbackSnapshotId) {
          return {
            action: "abort",
            message: `Rollback requested for stale run ${this.state.runId}, but no rollback snapshot was recorded.`,
            rollbackDisabled: true,
          };
        }

        try {
          workspaceManager.adoptSnapshot(this.state.rollbackSnapshotId);
          const rollbackResult = await workspaceManager.rollback();
          if (!rollbackResult.success) {
            const detail = rollbackResult.snapshotPath
              ? ` Snapshot retained at ${rollbackResult.snapshotPath}.`
              : "";
            return {
              action: "abort",
              message: `Rollback failed for stale run ${this.state.runId}.${detail}`,
              rollbackDisabled: false,
            };
          }

          this.tracker.markCompletedAndArchive();
          workspaceManager.cleanupAll();
          return {
            action: "proceed",
            message: "Stale run rolled back. Starting fresh loop run.",
            rollbackDisabled: false,
          };
        } finally {
          workspaceManager.releaseWorkspaceLock();
        }
      }

      case "finishRollback": {
        const confirmed = await prompts.promptFinishRollbackConfirm();
        if (!confirmed) {
          return { action: "abort", message: "Finish rollback cancelled by developer.", rollbackDisabled: false };
        }

        if (!this.state.rollbackSnapshotId) {
          return {
            action: "abort",
            message: `Finish rollback requested for stale run ${this.state.runId}, but no rollback snapshot was recorded.`,
            rollbackDisabled: true,
          };
        }

        try {
          workspaceManager.adoptSnapshot(this.state.rollbackSnapshotId);
          const rollbackResult = await workspaceManager.rollback();

          if (!rollbackResult.success) {
            this.tracker.recordPanicUndo({
              phase: "rollback-failed",
              rollbackFailedAt: new Date().toISOString(),
              snapshotRetained: rollbackResult.snapshotRetained,
              snapshotPath: rollbackResult.snapshotPath,
              affectedPaths: rollbackResult.affectedPaths,
            });
            const detail = rollbackResult.snapshotPath
              ? ` Snapshot retained at ${rollbackResult.snapshotPath}.`
              : "";
            return {
              action: "abort",
              message: `Rollback failed for stale run ${this.state.runId}.${detail}`,
              rollbackDisabled: false,
            };
          }

          workspaceManager.cleanupAll();

          console.warn(`  ⚠ Issue-status restore not available during startup recovery. Issue statuses may need manual cleanup.`);

          if (hasRemoteDivergence(this.state.repoCwd)) {
            console.warn(`  ⚠ Loop-created commits may have been pushed to a remote. Remote cleanup is manual.`);
          }

          this.tracker.recordPanicUndo({
            phase: "rollback-completed",
            rollbackCompletedAt: new Date().toISOString(),
            snapshotRetained: rollbackResult.snapshotRetained,
            snapshotPath: rollbackResult.snapshotPath,
            affectedPaths: rollbackResult.affectedPaths,
          });

          this.tracker.markStatusAndArchive("interrupted", "panic-undo");
          return {
            action: "proceed",
            message: "Partial panic-undo rollback completed. Run archived as interrupted.",
            rollbackDisabled: false,
          };
        } finally {
          workspaceManager.releaseWorkspaceLock();
        }
      }

      case "resume": {
        try {
          await this.prepareResume(git, workspaceManager, prompts);
        } catch (error) {
          if (error instanceof AbandonStaleRunError) {
            this.tracker.markCompletedAndArchive();
            return {
              action: "proceed",
              message: "Stale run abandoned. Starting new loop run.",
              rollbackDisabled: false,
            };
          }
          throw error;
        }
        this.tracker.adoptOwnership();
        return { action: "proceed", rollbackDisabled: this.state.rollbackSnapshotId == null };
      }
    }
  }

  public async prepareResume(
    git: GitClient,
    workspaceManager: WorkspaceManager,
    prompts: RecoveryPrompts,
  ): Promise<void> {
    const tasks = Object.values(this.state.tasks);

    for (const task of tasks) {
      switch (task.phase) {
        case "implementing":
          await prepareImplementingResume(task, workspaceManager);
          break;

        case "merge-pending":
        case "merging":
          await prepareMergingResume(task, git, workspaceManager, prompts);
          break;

        case "verify-pending":
        case "verifying":
          console.warn(`  ⚠ Task #${task.issueId} verification was interrupted. Verification will be rerun.`);
          break;

        case "mark-done-pending":
          console.warn(`  ⚠ Task #${task.issueId} completion marking was interrupted. Completion marking will be retried.`);
          break;

        case "done":
          if (task.integratedHead) {
            const reachable = git.isAncestor(task.integratedHead, "HEAD");
            if (!reachable) {
              console.warn(
                `\n  ⚠ Task #${task.issueId} is marked done but its integratedHead (${task.integratedHead.slice(0, 8)}) is not reachable from current HEAD.`,
              );
              console.warn(
                `  The task's integrated changes may have been lost. Manual developer decision required to continue.`,
              );
              if (prompts === ttyRecoveryPrompts && !process.stdin.isTTY) {
                throw new Error(
                  `Inconsistent done state for task #${task.issueId}: integratedHead ${task.integratedHead.slice(0, 8)} not reachable from HEAD. Cannot resume without developer input.`,
                );
              }
              const decision = await prompts.promptDoneInconsistency(task);
              if (decision === "restart") {
                if (this.tracker) {
                  this.tracker.restartTask(task.issueId);
                  this.state = this.tracker.read() ?? this.state;
                } else {
                  task.phase = "scheduled";
                  delete task.integratedHead;
                  delete task.preMergeHead;
                  delete task.lastError;
                  // C-4: state-form callers don't get a persisted restart. Production
                  // always passes a tracker; this branch only fires in tests using the
                  // state-form. Warn loudly so a future caller cannot silently drop the
                  // write the way the old code did.
                  console.warn(
                    `  \u26a0 restartTask called without a tracker for task #${task.issueId}; in-memory state mutated but not persisted. Pass a LoopRunTracker if persistence is required.`,
                  );
                }
              }
            }
          }
          break;
      }
    }

    if (this.state.review.phase === "running" || this.state.review.phase === "failed" || this.state.review.phase === "blocked") {
      console.warn("  ⚠ Whole-run review was interrupted, failed, or blocked. Review will be rerun.");
    }
  }
}

export function isPartialPanicUndo(state: LoopRunState): boolean {
  return new StaleRun(state).isPartialPanicUndo();
}

export function canFinishRollback(state: LoopRunState, _repoCwd: string): boolean {
  return new StaleRun(state).canFinishRollback();
}

export function getAvailableActions(state: LoopRunState): RecoveryChoice[] {
  return new StaleRun(state).getAvailableActions();
}

export async function handleStaleRun(
  tracker: LoopRunTracker,
  git: GitClient,
  workspaceManager: WorkspaceManager,
  prompts: RecoveryPrompts = ttyRecoveryPrompts,
): Promise<StaleRunRecoveryResult> {
  const state = tracker.read();

  if (!state) {
    return { action: "proceed", rollbackDisabled: false };
  }

  if (!tracker.isStale()) {
    return {
      action: "abort",
      message: `Active loop run detected (PID ${state.owner.pid}). Cannot start a new loop while another is running.`,
      rollbackDisabled: false,
    };
  }

  // When relying on the default TTY prompts but no TTY is attached, there is no
  // way to surface a choice — abort. Tests injecting a custom RecoveryPrompts
  // bypass this guard since they don't need stdin.
  if (prompts === ttyRecoveryPrompts && !process.stdin.isTTY) {
    return {
      action: "abort",
      message: `Stale loop run detected (runId: ${state.runId}). Use interactive mode (TTY) to resume, rollback, or abandon the stale run. No default recovery action will be selected.`,
      rollbackDisabled: false,
    };
  }

  const staleRun = StaleRun.fromTracker(tracker);
  if (!staleRun) {
    return { action: "proceed", rollbackDisabled: false };
  }

  staleRun.normalizeCrashRules();

  const actions = staleRun.getAvailableActions();
  const choice = await prompts.promptChoice(staleRun.getState(), actions);
  if (!actions.includes(choice)) {
    return {
      action: "abort",
      message: `Stale loop run recovery choice '${choice}' is not available in the current recovery state.`,
      rollbackDisabled: false,
    };
  }

  return staleRun.execute(choice, { git, workspaceManager, prompts });
}

export async function prepareStaleRunResume(
  stateOrTracker: LoopRunState | LoopRunTracker,
  git: GitClient,
  workspaceManager: WorkspaceManager,
  prompts: RecoveryPrompts = ttyRecoveryPrompts,
): Promise<void> {
  const tracker = stateOrTracker instanceof LoopRunTracker ? stateOrTracker : undefined;
  const state: LoopRunState | null = tracker
    ? tracker.read()
    : (stateOrTracker as LoopRunState);
  if (!state) {
    throw new Error("Cannot prepare stale-run resume without tracker state.");
  }

  const staleRun = new StaleRun(state, tracker);
  await staleRun.prepareResume(git, workspaceManager, prompts);
}

