/**
 * Resume plan for a {@link LoopRun}.
 *
 * Translates the persisted task table from a resumed Durable Loop Run
 * Tracker into the runtime state the scheduler needs:
 *
 *   • `replayQueue`     — in-flight tasks that must be re-scheduled
 *   • `terminalIds`     — issues already in a terminal phase (done/failed)
 *                         plus any `mark-done-pending` tasks that complete
 *                         during this call
 *   • `resumeIterations`/`resumeSkippedIds` — scheduler progress to
 *                         restore so iteration accounting and the
 *                         skipped-id allow-list pick up where they left off
 *
 * `mark-done-pending` tasks — those that finished verification but were
 * interrupted before the issue source's `markDone` returned — are
 * advanced to `done` here (calling `markDone` first if the source can't
 * confirm completion via `isDone`). This keeps the recovery path inside
 * one place instead of being inlined in `ralphLoop`.
 *
 * See ADR-0006 (Durable Loop Run Tracker and stale-run recovery).
 */

import type { LoopRun } from "./loop-run.js";
import type { RunSnapshot, TaskPhase } from "./state.js";
import type { Issue, IssueSource } from "../ralph-loop.js";

export interface ResumePlan {
  replayQueue: Issue[];
  terminalIds: Set<string | number>;
  resumeIterations: number;
  resumeSkippedIds: Set<string | number>;
}

export async function buildResumePlan(params: {
  loopRun: LoopRun;
  issueSource: IssueSource;
}): Promise<ResumePlan> {
  const { loopRun, issueSource } = params;
  const initialState = loopRun.snapshot();
  const allTasks = Object.values(initialState?.tasks ?? {});

  const terminalIds = new Set<string | number>(
    allTasks.filter((task) => isNonRetryableTerminalTaskPhase(task.phase)).map((task) => task.issueId),
  );

  // Advance any `mark-done-pending` tasks to `done`, calling the issue
  // source's `markDone` first when the source cannot confirm via `isDone`.
  const pendingCompletionTasks = allTasks.filter(
    (task) => task.phase === "mark-done-pending",
  );
  for (const task of pendingCompletionTasks) {
    const alreadyDone = await issueSource.isDone?.(task.issueId);
    if (!alreadyDone) {
      await issueSource.markDone({
        id: task.issueId,
        title: task.title,
        body: task.body ?? "",
      });
    }
    loopRun.recordTaskPhase(task.issueId, "done");
    terminalIds.add(task.issueId);
  }

  // Re-read after the `mark-done-pending → done` writes so scheduler
  // progress reflects any tracker updates emitted above.
  const refreshedState = loopRun.snapshot();
  const replayQueue = refreshedState
    ? Object.values(refreshedState.tasks)
      .filter((task) => !isTerminalTaskPhase(task.phase) && task.phase !== "mark-done-pending")
      .map(toTrackedIssue)
    : [];

  return {
    replayQueue,
    terminalIds,
    resumeIterations: refreshedState?.scheduler?.iterationsStarted ?? 0,
    resumeSkippedIds: new Set<string | number>(refreshedState?.scheduler?.skippedIds ?? []),
  };
}

function isTerminalTaskPhase(phase: TaskPhase): boolean {
  return phase === "done" || phase === "failed";
}

function isNonRetryableTerminalTaskPhase(phase: TaskPhase): boolean {
  return phase === "done";
}

function toTrackedIssue(task: RunSnapshot["tasks"][string]): Issue {
  return {
    id: task.issueId,
    title: task.title || `Issue ${task.issueId}`,
    body: task.body ?? "",
  };
}

/**
 * Persistence adapter for the Loop Run's `RunSnapshot` shape.
 *
 * The Loop Run owns the domain vocabulary in `../loop-run/state.ts` and
 * is the sole authoritative writer; this module turns that snapshot
 * into atomic, crash-safe, monotonic-revision JSON writes under
 * `.ralph-loop/runs/`. It is intentionally schema-free at the type
 * level — every type comes from `../loop-run/state.ts`.
 *
 * See ADR-0006 and ADR-0007.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync, renameSync, readdirSync, rmSync, statSync } from "node:fs";
import { join } from "node:path";

import type {
  IssueId,
  RunSnapshot,
  RunStatus,
  TerminalReason,
  PanicUndoState,
  TaskPhase,
  TaskMeta,
  ReviewPhase,
  SchedulerProgress,
  TaskRecord,
} from "../loop-run/state.js";
import { normalizeSteeringPostCrash } from "../loop-run/state.js";
import { buildUsageSummary } from "../loop-run/usage.js";

const RUNS_DIR = ".ralph-loop/runs";
const PROMPTS_DIR = ".ralph-loop/prompts";
const CRITERION_EVIDENCE_DIR = ".ralph-loop/criterion-evidence";
const HANDOFF_DIR = ".ralph-loop/handoffs";
const ACTIVE_FILE = "active.json";
const ARCHIVE_DIR = "archived";

function normalizeTaskRecord(task: TaskRecord): TaskRecord {
  return {
    ...task,
    criteria: Array.isArray(task.criteria) ? task.criteria : [],
    criterionIdentities: Array.isArray(task.criterionIdentities) ? task.criterionIdentities : [],
    liveSteering: Array.isArray(task.liveSteering) ? task.liveSteering : [],
  };
}

function normalizeRunSnapshot(state: RunSnapshot): RunSnapshot {
  return {
    ...state,
    tasks: Object.fromEntries(
      Object.entries(state.tasks ?? {}).map(([key, task]) => [key, normalizeTaskRecord(task)]),
    ),
  };
}

export class LoopRunTracker {
  private readonly runsDir: string;
  private readonly activeFilePath: string;
  private readonly archiveDir: string;

  constructor(private readonly cwd: string) {
    this.runsDir = join(cwd, RUNS_DIR);
    this.activeFilePath = join(this.runsDir, ACTIVE_FILE);
    this.archiveDir = join(this.runsDir, ARCHIVE_DIR);
  }

  create(params: {
    runId: string;
    repoCwd: string;
    startCommit: string;
    scheduler: {
      maxIterations: number;
      maxParallel: number;
      skippedIds: IssueId[];
    };
    rollbackSnapshotId?: string;
    capturePromptTranscripts?: boolean;
  }): RunSnapshot {
    const promptTranscripts =
      params.capturePromptTranscripts === false
        ? { enabled: false as const }
        : { enabled: true as const };

    const state: RunSnapshot = {
      runId: params.runId,
      revision: 1,
      repoCwd: params.repoCwd,
      startCommit: params.startCommit,
      status: "running",
      owner: {
        pid: process.pid,
        heartbeatAt: new Date().toISOString(),
      },
      scheduler: {
        maxIterations: params.scheduler.maxIterations,
        iterationsStarted: 0,
        maxParallel: params.scheduler.maxParallel,
        skippedIds: params.scheduler.skippedIds,
      },
      tasks: {},
      review: { phase: "pending" },
      rollbackSnapshotId: params.rollbackSnapshotId,
      promptTranscripts,
      usageLedger: [],
      usageSummary: buildUsageSummary([]),
    };

    this.atomicWrite(state);
    return state;
  }

  read(): RunSnapshot | null {
    this.cleanupTempFile();
    if (!existsSync(this.activeFilePath)) return null;
    const raw = readFileSync(this.activeFilePath, "utf8");
    return normalizeRunSnapshot(JSON.parse(raw) as RunSnapshot);
  }

  private cleanupTempFile(): void {
    const tmpPath = this.activeFilePath + ".tmp";
    if (existsSync(tmpPath) && !existsSync(this.activeFilePath)) {
      renameSync(tmpPath, this.activeFilePath);
    }
  }

  /**
   * Escape-hatch reducer-style update for callers that need to mutate
   * multiple snapshot fields atomically (e.g. stale-run recovery
   * restart surgery). Normal phase / meta / scheduler / review writes
   * should go through the targeted methods below.
   */
  update(updater: (state: RunSnapshot) => RunSnapshot): RunSnapshot {
    const current = this.read();
    if (!current) {
      throw new Error("Cannot update: no active tracker state found");
    }
    const next = updater(current);
    next.revision = current.revision + 1;
    this.atomicWrite(next);
    return next;
  }

  updateHeartbeat(): RunSnapshot {
    return this.update((s) => ({
      ...s,
      owner: { ...s.owner, heartbeatAt: new Date().toISOString() },
    }));
  }

  adoptOwnership(): RunSnapshot {
    return this.update((s) => ({
      ...s,
      status: "running",
      owner: {
        pid: process.pid,
        heartbeatAt: new Date().toISOString(),
      },
    }));
  }

  isOwnerAlive(): boolean {
    const state = this.read();
    if (!state) return false;
    try {
      process.kill(state.owner.pid, 0);
      return true;
    } catch {
      return false;
    }
  }

  isStale(maxAgeMs: number = 30_000): boolean {
    const state = this.read();
    if (!state) return true;
    if (!this.isOwnerAlive()) return true;
    const heartbeatTime = new Date(state.owner.heartbeatAt).getTime();
    return Date.now() - heartbeatTime > maxAgeMs;
  }

  markCompletedAndArchive(): RunSnapshot | null {
    return this.markStatusAndArchive("completed", undefined);
  }

  markStatus(status: RunStatus): RunSnapshot | null {
    const state = this.read();
    if (!state) return null;
    return this.update((current) => ({
      ...current,
      status,
    }));
  }

  recordReviewPhase(phase: ReviewPhase): void {
    this.update((s) => ({
      ...s,
      review: { phase },
    }));
  }

  recordPanicUndo(partial: Partial<PanicUndoState>): void {
    this.update((s) => ({
      ...s,
      panicUndo: { ...(s.panicUndo ?? { phase: "requested" }), ...partial },
    }));
  }

  markStatusAndArchive(status: RunStatus, terminalReason?: TerminalReason): RunSnapshot | null {
    const state = this.read();
    if (!state) return null;

    const completed: RunSnapshot = {
      ...state,
      status,
      ...(terminalReason ? { terminalReason } : {}),
    };

    this.atomicWrite(completed);

    if (!existsSync(this.archiveDir)) {
      mkdirSync(this.archiveDir, { recursive: true });
    }

    const archiveName = `completed-${Date.now()}-${state.runId}.json`;
    const archivePath = join(this.archiveDir, archiveName);

    renameSync(this.activeFilePath, archivePath);

    this.pruneArchive();

    return completed;
  }

  private pruneArchive(): void {
    if (!existsSync(this.archiveDir)) return;

    const files = readdirSync(this.archiveDir, { withFileTypes: true })
      .filter((f) => f.isFile() && f.name.endsWith(".json"))
      .map((f) => ({
        name: f.name,
        mtime: statSync(join(this.archiveDir, f.name)).mtimeMs,
      }))
