// Regression: bug 9. When the resume path advances mark-done-pending tasks to
// done, it must pass the persisted task body to issueSource.markDone. Custom
// sources (e.g. ones that re-post the body to a comment) behave differently
// when body is empty vs. populated.

import { describe, it, expect, vi } from "vitest";
import { buildResumePlan } from "../src/core/loop-run/resume-plan.js";

function fakeLoopRun(snapshot: any) {
  return {
    snapshot: vi.fn(() => snapshot),
    recordTaskPhase: vi.fn(),
  };
}

describe("buildResumePlan markDone body propagation", () => {
  it("passes task.body to markDone for mark-done-pending tasks", async () => {
    const snapshot = {
      tasks: {
        "1": {
          issueId: 1,
          title: "Persisted title",
          body: "Persisted body content",
          phase: "mark-done-pending",
        },
      },
      scheduler: { iterationsStarted: 0, skippedIds: [] },
    };

    const loopRun = fakeLoopRun(snapshot);
    const markDone = vi.fn().mockResolvedValue(undefined);
    const issueSource = {
      isDone: vi.fn().mockResolvedValue(false),
      markDone,
    };

    await buildResumePlan({ loopRun: loopRun as any, issueSource: issueSource as any });

    expect(markDone).toHaveBeenCalledOnce();
    expect(markDone).toHaveBeenCalledWith({
      id: 1,
      title: "Persisted title",
      body: "Persisted body content",
    });
  });

  it("falls back to empty body when task body is missing from snapshot", async () => {
    const snapshot = {
      tasks: {
        "2": {
          issueId: 2,
          title: "T",
          // body intentionally omitted to simulate legacy snapshot.
          phase: "mark-done-pending",
        },
      },
      scheduler: { iterationsStarted: 0, skippedIds: [] },
    };

    const loopRun = fakeLoopRun(snapshot);
    const markDone = vi.fn().mockResolvedValue(undefined);
    const issueSource = {
      isDone: vi.fn().mockResolvedValue(false),
      markDone,
    };

    await buildResumePlan({ loopRun: loopRun as any, issueSource: issueSource as any });

    expect(markDone).toHaveBeenCalledWith({
      id: 2,
      title: "T",
      body: "",
    });
  });

  it("skips markDone when isDone reports already complete", async () => {
    const snapshot = {
      tasks: {
        "3": {
          issueId: 3,
          title: "Already done",
          body: "irrelevant",
          phase: "mark-done-pending",
        },
      },
      scheduler: { iterationsStarted: 0, skippedIds: [] },
    };

    const loopRun = fakeLoopRun(snapshot);
    const markDone = vi.fn().mockResolvedValue(undefined);
    const issueSource = {
      isDone: vi.fn().mockResolvedValue(true),
      markDone,
    };

    await buildResumePlan({ loopRun: loopRun as any, issueSource: issueSource as any });

    expect(markDone).not.toHaveBeenCalled();
    expect(loopRun.recordTaskPhase).toHaveBeenCalledWith(3, "done");
  });
});

